import { useEffect, useRef, useState, type CSSProperties } from "react";
import { normalizeMaxScale } from "./geometry";
import { loadPlanarManifest } from "./manifest";
import { mountPlanarView, ZOOM_STEP, type PlanarControls, type PlanarStatus, type PlanarViewOptions } from "./runtime";

export type PlanarTileViewerProps = PlanarViewOptions & {
  /** A URL to manifest.json generated by pano-convert --projection planar. */
  manifestUrl: string;
  /** A description of the image for assistive technology. */
  alt: string;
  /** Shows the zoom and fit buttons. Defaults to true. */
  showZoomControls?: boolean;
  className?: string;
  style?: CSSProperties;
};

/** An independently mounted, zoomable viewer for one tiled flat image. */
export function PlanarTileViewer({
  manifestUrl, alt, maxScale, initialScale, dragMotion,
  showZoomControls = true, className, style,
}: PlanarTileViewerProps) {
  const viewport = useRef<HTMLDivElement>(null);
  const canvas = useRef<HTMLCanvasElement>(null);
  const controls = useRef<PlanarControls | null>(null);
  const options = useRef<PlanarViewOptions>({ maxScale, initialScale, dragMotion });
  const [attempt, setAttempt] = useState(0);
  const [status, setStatus] = useState<PlanarStatus>("loading");
  const zoomDisabled = status !== "ready" || normalizeMaxScale(maxScale) === 1;

  useEffect(() => {
    options.current = { maxScale, initialScale, dragMotion };
    controls.current?.configure(options.current);
  }, [maxScale, initialScale, dragMotion]);

  useEffect(() => {
    const viewportElement = viewport.current!;
    const canvasElement = canvas.current!;
    const controller = new AbortController();
    const { signal } = controller;
    setStatus("loading");
    void loadPlanarManifest(manifestUrl, signal).then((manifest) => {
      if (!signal.aborted) {
        controls.current = mountPlanarView(viewportElement, canvasElement, manifest, signal, setStatus, options.current);
      }
    }).catch(() => {
      if (!signal.aborted) setStatus("error");
    });
    return () => {
      controller.abort();
      controls.current = null;
    };
  }, [manifestUrl, attempt]);

  return (
    <div className={className ? `pano-planar-viewer ${className}` : "pano-planar-viewer"} style={style}>
      <div
        ref={viewport}
        className="pano-planar-viewport"
        role="region"
        aria-label={alt}
        aria-busy={status === "loading"}
        tabIndex={0}
      >
        <canvas ref={canvas} aria-hidden="true" />
      </div>
      {status !== "ready" && (
        <div className="pano-planar-status">
          <span role="status">{status === "loading" ? "Loading image…" : "Could not load image."}</span>
          {status === "error" && <button type="button" onClick={() => {
            viewport.current?.focus();
            setAttempt((value) => value + 1);
          }}>Retry</button>}
        </div>
      )}
      {showZoomControls && (
        <div className="pano-planar-controls" role="group" aria-label="Image controls">
          <button type="button" aria-label="Zoom out" disabled={zoomDisabled} onClick={() => controls.current?.zoom(1 / ZOOM_STEP)}>−</button>
          <button type="button" aria-label="Fit image" disabled={status !== "ready"} onClick={() => controls.current?.reset()}>Fit</button>
          <button type="button" aria-label="Zoom in" disabled={zoomDisabled} onClick={() => controls.current?.zoom(ZOOM_STEP)}>+</button>
        </div>
      )}
    </div>
  );
}
